import re
def space_prose(t):
 return re.sub(r'\b(approximately|preserves|having|positions|position|give|gives|width|stride|dilation|is|are|to|by|for|with|from|at|and|only|has|of)(?=[0-9])',r'\1 ',t)
for q in qs:
 q['stem']=space_prose(q['stem'])
 for o in q['options']:o['text']=space_prose(o['text'])
 for field in ['justification','simpleExplanation']:q['solution'][field]=space_prose(q['solution'][field])
 for field in ['steps','misconceptions']:q['solution'][field]=[space_prose(t)for t in q['solution'][field]]
 q['solution']['optionExplanations']={k:space_prose(v)for k,v in q['solution']['optionExplanations'].items()}
